let triggerInput = {};
try {
  triggerInput = $('webhook-openrouter-telemetry-trigger').first().json.body || {};
} catch (e) {
  triggerInput = {};
}

const httpResponse = $json;
const keysList = httpResponse.body?.data || httpResponse.data || [];

// Find earliest created_at among keys, or default to 365 days ago
let earliestDate = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000);
keysList.forEach(k => {
  if (k.created_at) {
    const d = new Date(k.created_at);
    if (d < earliestDate) earliestDate = d;
  }
});

const startDate = earliestDate.toISOString();
const endDate = new Date().toISOString(); // Today dynamically (now)
const apiKey = triggerInput.apiKey || '';

return {
  apiKey: apiKey,
  startDate: startDate,
  endDate: endDate,
  keysList: keysList,
  connectionName: triggerInput.connectionName || 'Enterprise OpenRouter Gateway',
  productTag: triggerInput.productTag || 'SHARED_GATEWAY'
};

let prepData = {};
try {
  prepData = $('code-prepare-query-dates').first().json || $('Prepare Dynamic Date Range').first().json || {};
} catch (e) {
  prepData = {};
}

let dateAnalyticsResp = {};
try {
  dateAnalyticsResp = $('http-fetch-datewise-analytics').first().json || {};
} catch (e) {
  dateAnalyticsResp = {};
}

const rawKeys = prepData.keysList || [];
const rawDateAnalytics = dateAnalyticsResp.body?.data || dateAnalyticsResp.data || [];
const rawAppAnalytics = $json.body?.data || $json.data || [];

// 1. Process Date-Wise Telemetry Rows strictly from API
let totalSpend = 0;
let totalPromptTokens = 0;
let totalCompletionTokens = 0;
let totalCachedTokens = 0;
let totalRequests = 0;

const dateWiseTelemetry = Array.isArray(rawDateAnalytics) ? rawDateAnalytics.map(row => {
  const cost = typeof row.cost === 'number' ? Number(row.cost.toFixed(4)) : (Number(row.cost) || 0);
  const promptTok = Number(row.prompt_tokens || row.input_tokens || 0);
  const compTok = Number(row.completion_tokens || row.output_tokens || 0);
  const cachedTok = Number(row.cached_tokens || 0);
  const requests = Number(row.request_count || 0);

  totalSpend += cost;
  totalPromptTokens += promptTok;
  totalCompletionTokens += compTok;
  totalCachedTokens += cachedTok;
  totalRequests += requests;

  return {
    date: row.date || '',
    model: row.model || '',
    keyName: row.key_name || row.key || '',
    keyLabel: row.key_label || '',
    app: row.app || '',
    promptTokens: promptTok,
    completionTokens: compTok,
    cachedTokens: cachedTok,
    cached: cachedTok > 0,
    cost: cost,
    requests: requests
  };
}) : [];

// 2. Compute Unit Economics from live totals
const totalTokens = totalPromptTokens + totalCompletionTokens;
const cacheHitRate = totalPromptTokens > 0 
  ? Number(((totalCachedTokens / totalPromptTokens) * 100).toFixed(1)) 
  : 0;
const blendedPerMillion = totalTokens > 0 
  ? Number(((totalSpend / totalTokens) * 1000000).toFixed(2)) 
  : 0;

// 3. Aggregate Model Breakdown
const modelMap = {};
dateWiseTelemetry.forEach(t => {
  if (t.model) {
    if (!modelMap[t.model]) {
      modelMap[t.model] = {
        model: t.model,
        cost: 0,
        promptTokens: 0,
        completionTokens: 0,
        cachedTokens: 0,
        requests: 0
      };
    }
    modelMap[t.model].cost += t.cost;
    modelMap[t.model].promptTokens += t.promptTokens;
    modelMap[t.model].completionTokens += t.completionTokens;
    modelMap[t.model].cachedTokens += t.cachedTokens;
    modelMap[t.model].requests += t.requests;
  }
});

const modelBreakdown = Object.values(modelMap).map(m => ({
  ...m,
  cost: Number(m.cost.toFixed(4)),
  share: totalSpend > 0 ? Number(((m.cost / totalSpend) * 100).toFixed(1)) : 0
}));

// 4. Process App Breakdown strictly from API
const appBreakdown = Array.isArray(rawAppAnalytics) ? rawAppAnalytics.map(a => ({
  app: a.app || '',
  cost: Number((Number(a.cost) || 0).toFixed(4)),
  promptTokens: Number(a.prompt_tokens || 0),
  completionTokens: Number(a.completion_tokens || 0),
  requests: Number(a.request_count || 0)
})) : [];

// 5. Calculate total usage across keys
let keysTotalUsage = 0;
let keysTotalLimit = 0;
let keysTotalRemaining = 0;

const parsedKeys = rawKeys.map(k => {
  const u = typeof k.usage === 'number' ? k.usage : 0;
  const l = typeof k.limit === 'number' ? k.limit : null;
  const r = typeof k.limit_remaining === 'number' ? k.limit_remaining : (l !== null ? Math.max(0, l - u) : null);
  keysTotalUsage += u;
  if (l !== null) keysTotalLimit += l;
  if (r !== null) keysTotalRemaining += r;
  return {
    name: k.name || '',
    label: k.label || '',
    usage: Number(u.toFixed(4)),
    limit: l !== null ? Number(l.toFixed(2)) : null,
    remaining: r !== null ? Number(r.toFixed(4)) : null,
    createdAt: k.created_at || null,
    disabled: Boolean(k.disabled)
  };
});

// 6. FinOps FOCUS 1.0 Standard Normalization
const focusRecords = dateWiseTelemetry.map((t, idx) => ({
  ChargePeriodStart: t.date ? `${t.date}T00:00:00.000Z` : prepData.startDate,
  ChargePeriodEnd: t.date ? `${t.date}T23:59:59.999Z` : prepData.endDate,
  ProviderName: 'OpenRouter',
  BillingAccountId: rawKeys[0]?.workspace_id || 'openrouter-workspace',
  SubAccountId: t.keyLabel || 'primary-key',
  SubAccountName: t.keyName || 'Workspace Key',
  ServiceName: 'OpenRouter AI Inference',
  ServiceCategory: 'AI and Machine Learning',
  SkuId: t.model,
  UsageQuantity: t.promptTokens + t.completionTokens,
  UsageUnit: 'Tokens',
  BilledCost: t.cost,
  EffectiveCost: t.cost,
  Tags: {
    Application: t.app || 'Direct API',
    Product: prepData.productTag || 'SHARED_GATEWAY',
    Environment: 'Production'
  }
}));

const finalTotalCost = totalSpend > 0 ? Number(totalSpend.toFixed(2)) : Number(keysTotalUsage.toFixed(2));

return {
  success: true,
  connectionId: 'or_conn_' + Math.random().toString(36).substring(2, 10),
  connectionName: prepData.connectionName || 'Enterprise OpenRouter Gateway',
  productTag: prepData.productTag || 'SHARED_GATEWAY',
  workspaceId: rawKeys[0]?.workspace_id || '',

  // FinOps KPI Summary (Strictly Live)
  totalUsage: finalTotalCost,
  creditLimit: Number(keysTotalLimit.toFixed(2)),
  remainingBalance: Number(keysTotalRemaining.toFixed(2)),
  totalTokens: totalTokens,
  totalPromptTokens: totalPromptTokens,
  totalCompletionTokens: totalCompletionTokens,
  totalCachedTokens: totalCachedTokens,
  cacheHitRate: cacheHitRate,
  blendedRate: `$${blendedPerMillion} / 1M`,
  totalRequests: totalRequests,

  // FinOps FOCUS 1.0 Normalized Dataset
  focusRecords: focusRecords,

  // Granular Live Arrays
  keysList: parsedKeys,
  dateWiseTelemetry: dateWiseTelemetry,
  modelBreakdown: modelBreakdown,
  appBreakdown: appBreakdown,
  startDate: prepData.startDate,
  endDate: prepData.endDate,
  lastSyncedAt: new Date().toISOString()
};
